const GameStateEventSchema = z
  .object({
    type: z.literal('gameState'),
    moves: z
      .string()
      .openapi({
        description:
          'Current moves in UCI format (King to rook for Chess690-compatible castling\nnotation)\n',
      }),
    wtime: z.int().openapi({ description: 'Integer of milliseconds White has left on the clock' }),
    btime: z.int().openapi({ description: 'Integer of milliseconds Black has left on the clock' }),
    winc: z.int().openapi({ description: 'Integer of White Fisher increment.' }),
    binc: z.int().openapi({ description: 'Integer of Black Fisher increment.' }),
    status: GameStatusNameSchema,
    winner: GameColorSchema.exactOptional().openapi({ description: 'Color of the winner, if any' }),
    wdraw: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'true if white is offering draw, else omitted' }),
    bdraw: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'true if black is offering draw, else omitted' }),
    wtakeback: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'true if white is proposing takeback, else omitted' }),
    btakeback: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'true if black is proposing takeback, else omitted' }),
    expiration: z
      .object({
        idleMillis: z
          .int()
          .openapi({
            description: 'Milliseconds since the last move was played, or since the game started',
          }),
        millisToMove: z
          .int()
          .openapi({
            description:
              'Time each player has to make their first move, before the game is aborted',
          }),
      })
      .exactOptional()
      .openapi({
        description: "A game may be aborted if a player doesn't make their first move in time",
        required: ['idleMillis', 'millisToMove'],
      }),
  })
  .openapi({ required: ['type', 'moves', 'wtime', 'btime', 'winc', 'binc', 'status'] })
  .openapi('GameStateEvent')

const GameFullEventSchema = z
  .object({
    type: z.literal('gameFull'),
    id: z.string(),
    variant: VariantSchema,
    clock: z
      .object({
        initial: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .exactOptional()
          .openapi({
            type: 'integer',
            format: 'int64',
            description: 'Initial time in milliseconds',
          }),
        increment: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .exactOptional()
          .openapi({
            type: 'integer',
            format: 'int64',
            description: 'Increment time in milliseconds',
          }),
      })
      .exactOptional()
      .openapi({ required: [] }),
    speed: SpeedSchema,
    perf: z
      .object({
        name: z
          .string()
          .exactOptional()
          .openapi({ description: 'Translated perf name (e.g. "Classical" or "Blitz")' }),
      })
      .openapi({ required: [] }),
    rated: z.boolean(),
    createdAt: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64' }),
    white: GameEventPlayerSchema,
    black: GameEventPlayerSchema,
    initialFen: z.string().default('startpos'),
    state: GameStateEventSchema,
    daysPerTurn: z.int().exactOptional().openapi({ description: 'If the game is correspondence' }),
    tournamentId: z.string().exactOptional(),
  })
  .openapi({
    required: [
      'type',
      'id',
      'variant',
      'speed',
      'perf',
      'rated',
      'createdAt',
      'white',
      'black',
      'initialFen',
      'state',
    ],
  })
  .openapi('GameFullEvent')

