export const getApiUsersStatusRoute = createRoute({
  method: 'get',
  path: '/api/users/status',
  tags: ['Users'],
  summary: 'Get real-time users status',
  description:
    "Read the `online`, `playing` and `streaming` flags of several users.\nThis API is very fast and cheap on lichess side.\nSo you can call it quite often (like once every 5 seconds).\nUse it to track players and know when they're connected on lichess and playing games.\n",
  operationId: 'apiUsersStatus',
  request: {
    query: z.object({
      ids: z
        .string()
        .openapi({
          param: {
            in: 'query',
            name: 'ids',
            required: true,
            description: 'User IDs separated by commas. Up to 100 IDs.',
            schema: { type: 'string' },
            example: 'thibault,maia1,maia5',
          },
        }),
      withSignal: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'withSignal',
            required: false,
            description:
              'Also return the network signal of the player, when available.\nIt ranges from 1 (poor connection, lag > 500ms) to 4 (great connection, lag < 150ms)\nDefaults to `false` to preserve server resources.\n',
            schema: { type: 'boolean' },
            example: true,
          },
        }),
      withGameIds: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'withGameIds',
            required: false,
            description:
              'Also return the ID of the game being played, if any, for each player, in a `playingId` field.\nDefaults to `false` to preserve server resources.\n',
            schema: { type: 'boolean' },
            example: true,
          },
        }),
      withGameMetas: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'withGameMetas',
            required: false,
            description:
              'Also return the id, time control and variant of the game being played, if any, for each player, in a `playing` field.\nDefaults to `false` to preserve server resources. Disables `withGameIds`.\n',
            schema: { type: 'boolean' },
            example: true,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The list of users and their respective statuses.',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                id: z.string(),
                name: z.string(),
                flair: FlairSchema.exactOptional(),
                title: TitleSchema.exactOptional(),
                online: z.boolean().exactOptional(),
                playing: z.boolean().exactOptional(),
                streaming: z.boolean().exactOptional(),
                patron: PatronSchema.exactOptional(),
                patronColor: PatronColorSchema.exactOptional(),
              })
              .openapi({ required: ['id', 'name'] }),
          ),
          examples: { default: UsersGetRealTimeUsersStatusJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
  },
  security: [],
})

