export const getApiPuzzleBatchAngleRoute = createRoute({
  method: 'get',
  path: '/api/puzzle/batch/{angle}',
  tags: ['Puzzles'],
  summary: 'Get multiple puzzles at once',
  description:
    'Get a batch of random Lichess puzzles in JSON format.\n\nIf authenticated, only returns puzzles that the user has never seen before.\n\n**DO NOT** use this endpoint to enumerate puzzles for mass download. Instead, download the [full public puzzle database](https://database.lichess.org/#puzzles).\n',
  operationId: 'apiPuzzleBatchSelect',
  request: {
    params: z.object({
      angle: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'angle',
            schema: { type: 'string', example: 'mix' },
            required: true,
            description:
              'The theme or opening to filter puzzles with. Recommended: `mix`.\n\nAvailable themes are listed in [the lichess source code](https://github.com/ornicar/lila/blob/master/translation/source/puzzleTheme.xml) and [the lichess training themes hyperlinks](https://lichess.org/training/themes).\n',
          },
          example: 'mix',
        }),
    }),
    query: z.object({
      difficulty: z
        .enum(['easiest', 'easier', 'normal', 'harder', 'hardest'])
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'difficulty',
            required: false,
            description:
              'The desired puzzle difficulty, relative to the authenticated user puzzle rating, or 1500 if anonymous.',
            schema: { type: 'string', enum: ['easiest', 'easier', 'normal', 'harder', 'hardest'] },
          },
        }),
      nb: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(50),
        )
        .default(15)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'nb',
            description:
              'How many puzzles to fetch. Just set it to `1` if you only need one puzzle.\n',
            schema: { type: 'integer', minimum: 1, maximum: 50, example: 10, default: 15 },
            required: false,
          },
          example: 10,
        }),
      color: z
        .enum(['white', 'black'])
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'color',
            required: false,
            description:
              'The color to play. Better left empty to automatically get 50% white.\nCurrently only works when `nb=1`.\n',
            schema: { type: 'string', enum: ['white', 'black'] },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The requested puzzles.',
      content: {
        'application/json': {
          schema: PuzzleBatchSelectSchema,
          examples: { default: PuzzlesGetMultiplePuzzlesAtOnceJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
  },
  security: [{ OAuth2: ['puzzle:read'] }],
})

