export const getApiPuzzleActivityRoute = createRoute({
  method: 'get',
  path: '/api/puzzle/activity',
  tags: ['Puzzles'],
  summary: 'Get your puzzle activity',
  description:
    'Download your puzzle activity in [ndjson](#description/streaming-with-nd-json) format.\nPuzzle activity is sorted by reverse chronological order (most recent first)\nWe recommend streaming the response, for it can be very long.\n',
  operationId: 'apiPuzzleActivity',
  request: {
    query: z.object({
      max: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'max',
            description: 'How many entries to download. Leave empty to download all activity.',
            schema: { type: 'integer', minimum: 1 },
            required: false,
          },
        }),
      before: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1356998400070),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'before',
            description:
              'Download entries before this timestamp. Defaults to now. Use `before` and `max` for pagination.',
            schema: { type: 'integer', minimum: 1356998400070 },
            required: false,
          },
        }),
      since: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1356998400070),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'since',
            description:
              'Download entries since this timestamp. Defaults to account creation date.',
            schema: { type: 'integer', minimum: 1356998400070 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The puzzle activity of the logged in user.',
      content: {
        'application/x-ndjson': {
          schema: PuzzleActivitySchema,
          examples: { default: PuzzlesGetYourPuzzleActivityJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
  },
  security: [{ OAuth2: ['puzzle:read'] }],
})

