export const getApiTvChannelRoute = createRoute({
  method: 'get',
  path: '/api/tv/{channel}',
  tags: ['TV'],
  summary: 'Get best ongoing games of a TV channel',
  description:
    'Get a list of ongoing games for a given TV channel. Similar to [lichess.org/games](https://lichess.org/games).\nAvailable in PGN or [ndjson](#description/streaming-with-nd-json) format, depending on the request `Accept` header.\n',
  operationId: 'tvChannelGames',
  request: {
    headers: z.object({ Accept: AcceptPgnOrNdjsonParamsSchema }),
    params: z.object({
      channel: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'channel',
            description: 'The name of the channel in camel case.',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
    query: z.object({
      nb: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(30),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'nb',
            description: 'Number of games to fetch.',
            schema: { type: 'integer', default: 10, minimum: 1, maximum: 30 },
            required: false,
          },
        }),
      moves: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'moves',
            description: 'Include the PGN moves.',
            schema: { type: 'boolean', default: true },
            required: false,
          },
        }),
      pgnInJson: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'pgnInJson',
            description: 'Include the full PGN within the JSON response, in a `pgn` field.',
            schema: { type: 'boolean', default: false },
            required: false,
          },
        }),
      tags: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'tags',
            description: 'Include the PGN tags.',
            schema: { type: 'boolean', default: true },
            required: false,
          },
        }),
      clocks: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'clocks',
            description:
              'Include clock status when available.\nEither as PGN comments: `2. exd5 { [%clk 1:01:27] } e5 { [%clk 1:01:28] }`\nOr in a `clocks` JSON field, as centisecond integers, depending on the response type.\n',
            schema: { type: 'boolean', default: false },
            required: false,
          },
        }),
      opening: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'opening',
            description:
              'Include the opening name.\nExample: `[Opening "King\'s Gambit Accepted, King\'s Knight Gambit"]`\n',
            schema: { type: 'boolean', default: false },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The representation of the games.',
      content: {
        'application/x-chess-pgn': {
          schema: GamePgnSchema,
          examples: { pgn: TvGetBestOngoingGamesOfTvChannelPgnExample },
        },
        'application/x-ndjson': {
          schema: GameJsonSchema,
          examples: { default: TvGetBestOngoingGamesOfTvChannelJsonExample },
        },
      },
    },
  },
  security: [],
})

