export const getApiTournamentIdResultsRoute = createRoute({
  method: 'get',
  path: '/api/tournament/{id}/results',
  tags: ['Tournaments (Arena)'],
  summary: 'Get results of an Arena tournament',
  description:
    'Players of an Arena tournament, with their score and performance, sorted by rank (best first).\n**Players are streamed as [ndjson](#description/streaming-with-nd-json)**, i.e. one JSON object per line.\nIf called on an ongoing tournament, results can be inconsistent\ndue to ranking changes while the players are being streamed.\nUse on finished tournaments for guaranteed consistency.\n',
  operationId: 'resultsByTournament',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'id',
            description: 'The tournament ID.',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
    query: z.object({
      nb: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'nb',
            description: 'Max number of players to fetch',
            schema: { type: 'integer', minimum: 1 },
            required: false,
          },
        }),
      sheet: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'sheet',
            description:
              "Add a `sheet` field to the player document.\nIt's an expensive server computation that slows down the stream.\n",
            schema: { type: 'boolean', default: false },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The results of the Arena tournament.',
      content: {
        'application/x-ndjson': {
          schema: z
            .object({
              rank: z.int(),
              score: z.int(),
              rating: z.int(),
              username: z.string(),
              performance: z.int(),
              title: TitleSchema.exactOptional(),
              team: z.string().exactOptional(),
              flair: FlairSchema.exactOptional(),
              patronColor: PatronColorSchema.exactOptional(),
              sheet: ArenaSheetSchema.exactOptional(),
            })
            .openapi({ required: ['rank', 'score', 'rating', 'username', 'performance'] }),
          examples: { default: ArenasGetResultsOfArenaJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
  },
  security: [],
})

