export const postApiSwissIdEditRoute = createRoute({
  method: 'post',
  path: '/api/swiss/{id}/edit',
  tags: ['Tournaments (Swiss)'],
  summary: 'Update a Swiss tournament',
  description:
    'Update a Swiss tournament.\nBe mindful not to make important changes to ongoing tournaments.\nAdditional restrictions:\n  - clock.limit + clock.increment > 0\n  - 15s and 0+1 variant tournaments cannot be rated\n',
  operationId: 'apiSwissUpdate',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'id',
            description: 'The tournament ID.',
            schema: { type: 'string', example: 'hL7vMrFQ' },
            required: true,
          },
          example: 'hL7vMrFQ',
        }),
    }),
    body: {
      description: 'Parameters of the tournament',
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              name: z
                .string()
                .min(2)
                .max(30)
                .exactOptional()
                .openapi({
                  description: 'The tournament name. Leave empty to get a random Grandmaster name',
                }),
              'clock.limit': z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.union([
                    z.literal(0),
                    z.literal(15),
                    z.literal(30),
                    z.literal(45),
                    z.literal(60),
                    z.literal(90),
                    z.literal(120),
                    z.literal(180),
                    z.literal(240),
                    z.literal(300),
                    z.literal(360),
                    z.literal(420),
                    z.literal(480),
                    z.literal(600),
                    z.literal(900),
                    z.literal(1200),
                    z.literal(1500),
                    z.literal(1800),
                    z.literal(2400),
                    z.literal(3000),
                    z.literal(3600),
                    z.literal(4200),
                    z.literal(4800),
                    z.literal(5400),
                    z.literal(6000),
                    z.literal(6600),
                    z.literal(7200),
                    z.literal(7800),
                    z.literal(8400),
                    z.literal(9000),
                    z.literal(9600),
                    z.literal(10200),
                    z.literal(10800),
                  ]),
                )
                .openapi({ description: 'Clock initial time in seconds', example: 300 }),
              'clock.increment': z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(0).max(120),
                )
                .openapi({ description: 'Clock increment in seconds', example: 1 }),
              nbRounds: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(3).max(100),
                )
                .openapi({ description: 'Maximum number of rounds to play' }),
              startsAt: z
                .preprocess((val) => {
                  if (
                    typeof val !== 'string' ||
                    !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val)
                  )
                    return val
                  if (/^-?\d+$/.test(val)) return BigInt(val)
                  const num = Number(val)
                  return Number.isSafeInteger(num) ? BigInt(num) : val
                }, z.int64())
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description:
                    'Timestamp in milliseconds to start the tournament at a given date and time. By default, it starts 10 minutes after creation.',
                }),
              roundInterval: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.union([
                    z.literal(-1),
                    z.literal(5),
                    z.literal(10),
                    z.literal(20),
                    z.literal(30),
                    z.literal(45),
                    z.literal(60),
                    z.literal(120),
                    z.literal(180),
                    z.literal(300),
                    z.literal(600),
                    z.literal(900),
                    z.literal(1200),
                    z.literal(1800),
                    z.literal(2700),
                    z.literal(3600),
                    z.literal(86400),
                    z.literal(172800),
                    z.literal(604800),
                    z.literal(99999999),
                  ]),
                )
                .exactOptional()
                .openapi({
                  description:
                    'How long to wait between each round, in seconds.\nSet to 99999999 to manually schedule each round from the tournament UI, or [with the API](#tag/tournaments-swiss/POST/api/swiss/{id}/schedule-next-round).\nIf empty or -1, a sensible value is picked automatically.\n',
                }),
              variant: VariantKeySchema.exactOptional(),
              position: SwissFromPositionFENSchema.exactOptional(),
              description: z
                .string()
                .exactOptional()
                .openapi({ description: 'Anything you want to tell players about the tournament' }),
              rated: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(true)
                .exactOptional()
                .openapi({ description: 'Games are rated and impact players ratings' }),
              password: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Make the tournament private and restrict access with a password.',
                }),
              forbiddenPairings: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Usernames of players that must not play together.\nTwo usernames per line, separated by a space.\n',
                }),
              manualPairings: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Manual pairings for the next round.\nTwo usernames per line, separated by a space.\nPresent players without a valid pairing will be given a bye, which is worth 1 point.\nForfeited players will get 0 points.\n',
                }),
              chatFor: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.union([z.literal(0), z.literal(10), z.literal(20), z.literal(30)]),
                )
                .default(20)
                .exactOptional()
                .openapi({
                  description:
                    'Who can read and write in the chat.\n- 0  = No-one\n- 10 = Only team leaders\n- 20 = Only team members\n- 30 = All Lichess players\n',
                }),
              'conditions.minRating.rating': z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.union([
                    z.literal(1000),
                    z.literal(1100),
                    z.literal(1200),
                    z.literal(1300),
                    z.literal(1400),
                    z.literal(1500),
                    z.literal(1600),
                    z.literal(1700),
                    z.literal(1800),
                    z.literal(1900),
                    z.literal(2000),
                    z.literal(2100),
                    z.literal(2200),
                    z.literal(2300),
                    z.literal(2400),
                    z.literal(2500),
                    z.literal(2600),
                  ]),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Minimum rating to join. Leave empty to let everyone join the tournament.',
                }),
              'conditions.maxRating.rating': z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.union([
                    z.literal(2200),
                    z.literal(2100),
                    z.literal(2000),
                    z.literal(1900),
                    z.literal(1800),
                    z.literal(1700),
                    z.literal(1600),
                    z.literal(1500),
                    z.literal(1400),
                    z.literal(1300),
                    z.literal(1200),
                    z.literal(1100),
                    z.literal(1000),
                    z.literal(900),
                    z.literal(800),
                  ]),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Maximum rating to join. Based on best rating reached in the last 7 days. Leave empty to let everyone join the tournament.',
                }),
              'conditions.nbRatedGame.nb': z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(0).max(200),
                )
                .exactOptional()
                .openapi({ description: 'Minimum number of rated games required to join.' }),
              'conditions.playYourGames': z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    "Only let players join if they have played their last swiss game.\nIf they failed to show up in a recent swiss event, they won't be able to enter yours.\nThis results in a better swiss experience for the players who actually show up.\n",
                }),
              'conditions.allowList': z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Predefined list of usernames that are allowed to join, separated by commas.\nIf this list is non-empty, then usernames absent from this list will be forbidden to join.\nAdding `%titled` to the list additionally allows any titled player to join.\nExample: `thibault,german11,%titled`\n',
                }),
            })
            .openapi({ required: ['clock.limit', 'clock.increment', 'nbRounds'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'The Swiss tournament was successfully updated.',
      content: {
        'application/json': {
          schema: SwissTournamentSchema,
          examples: { default: SwissUpdateSwissJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
    400: {
      description: 'Updating the swiss failed.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
    401: {
      description: 'This user cannot update this Swiss.',
      content: { 'application/json': { schema: SwissUnauthorisedEditSchema } },
    },
  },
  security: [{ OAuth2: ['tournament:write'] }],
})

