export const postApiStudyRoute = createRoute({
  method: 'post',
  path: '/api/study',
  tags: ['Studies'],
  summary: 'Create a new Study',
  description:
    'Create a [study](https://lichess.org/study), and a new empty chapter within it.\nYou can make up to 30 new studies per day.\n',
  operationId: 'apiStudyPost',
  request: {
    body: {
      description: 'Parameters of the study',
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              name: z.string().min(2).max(100).openapi({ description: 'The study name.' }),
              visibility: z
                .enum(['public', 'unlisted', 'private'])
                .default('unlisted')
                .openapi({
                  description:
                    "Who can view the study.\n* `public`: Default. Anyone can view the study, it appears on public listings\n* `unlisted`: Only people with the link can view the study, it doesn't appear on public listings\n* `private`: Only the study members can view the study\n",
                }),
              flair: FlairSchema.exactOptional(),
              computer: StudyUserSelectionSchema,
              explorer: StudyUserSelectionSchema,
              cloneable: StudyUserSelectionSchema,
              shareable: StudyUserSelectionSchema,
              chat: StudyUserSelectionSchema,
              sticky: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(true)
                .exactOptional()
                .openapi({ description: 'Keep everyone on the same chapter and position.' }),
              description: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(false)
                .exactOptional()
                .openapi({ description: 'Add pinned study comment right under the board.' }),
            })
            .openapi({
              required: [
                'name',
                'visibility',
                'computer',
                'explorer',
                'cloneable',
                'shareable',
                'chat',
              ],
            }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'The Study has been successfully created.',
      content: {
        'application/json': {
          schema: z.object({ id: z.string().exactOptional() }).openapi({ required: [] }),
          examples: { default: StudiesCreateStudyJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
    400: {
      description: 'The creation of the Study failed.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ OAuth2: ['study:write'] }],
})

export const postApiStudyStudyIdImportPgnRoute = createRoute({
  method: 'post',
  path: '/api/study/{studyId}/import-pgn',
  tags: ['Studies'],
  summary: 'Import PGN into a study',
  description:
    'Imports arbitrary PGN into an existing [study](https://lichess.org/study). Creates a new chapter in the study.\nIf the PGN contains multiple games (separated by 2 or more newlines)\nthen multiple chapters will be created within the study.\nNote that a study can contain at most 64 chapters.\n',
  operationId: 'apiStudyImportPGN',
  request: {
    params: z.object({
      studyId: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'studyId',
            description: 'ID of the study',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
    body: {
      description: 'Parameters of the import',
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              pgn: z
                .string()
                .openapi({
                  description:
                    'PGN to import. Can contain multiple games separated by 2 or more newlines.\n',
                }),
              name: z
                .string()
                .min(1)
                .max(100)
                .exactOptional()
                .openapi({
                  description:
                    'Name of the new chapter.\nIf not specified, or if multiple chapters are created, the names will be inferred from the PGN tags.\n',
                }),
              orientation: z
                .enum(['white', 'black'])
                .exactOptional()
                .openapi({
                  description:
                    'Board orientation.\nIf not specified, the orientation is automatically determined.\n',
                }),
              variant: VariantKeySchema.exactOptional(),
              mode: z
                .enum(['practice', 'conceal', 'gamebook'])
                .exactOptional()
                .openapi({
                  description:
                    'Analysis mode.\nIf not specified, Normal analysis.\n* practice - Practise with Computer\n* conceal - Hide next moves\n* gamebook - Interactive lesson\n',
                }),
            })
            .openapi({ required: ['pgn'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'The chapters that were created.',
      content: {
        'application/json': {
          schema: StudyImportPgnChaptersSchema,
          examples: { default: StudiesImportPgnIntoStudyJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
    400: {
      description: 'The creation of the chapter(s) failed.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ OAuth2: ['study:write'] }],
})

