export const getApiBroadcastRoute = createRoute({
  method: 'get',
  path: '/api/broadcast',
  tags: ['Broadcasts'],
  summary: 'Get official broadcasts',
  description:
    'Returns active (a round is scheduled or ongoing) official broadcasts sorted by tier. \nAfter that, returns finished broadcasts sorted by most recent sync time.\nBroadcasts are streamed as [ndjson](#description/streaming-with-nd-json).\n',
  operationId: 'broadcastsOfficial',
  request: {
    query: z.object({
      nb: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'nb',
            description: 'Max number of broadcasts to fetch',
            schema: { type: 'integer', default: 20, minimum: 1, maximum: 100 },
            required: false,
          },
        }),
      html: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'html',
            description: 'Convert the "description" field from markdown to HTML',
            schema: { type: 'boolean' },
            example: true,
            required: false,
          },
        }),
      live: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'live',
            description:
              '[Filter] only broadcasts where a round is ongoing, i.e. started and not finished',
            schema: { type: 'boolean' },
            example: true,
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The list of official broadcasts.',
      content: {
        'application/x-ndjson': {
          schema: BroadcastWithRoundsSchema,
          examples: { default: BroadcastsGetOfficialBroadcastsJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
  },
  security: [],
})

