export const postBroadcastBroadcastTournamentIdEditRoute = createRoute({
  method: 'post',
  path: '/broadcast/{broadcastTournamentId}/edit',
  tags: ['Broadcasts'],
  summary: 'Update your broadcast tournament',
  description:
    'Update information about a broadcast tournament that you created.\nThis endpoint accepts the same form data as the web form.\nAll fields must be populated with data. Missing fields will override the broadcast with empty data.\n',
  operationId: 'broadcastTourUpdate',
  request: {
    params: z.object({
      broadcastTournamentId: z
        .string()
        .length(8)
        .openapi({
          param: {
            in: 'path',
            name: 'broadcastTournamentId',
            description: 'The broadcast ID',
            required: true,
            schema: { type: 'string', minLength: 8, maxLength: 8 },
          },
        }),
    }),
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              name: z
                .string()
                .min(3)
                .max(80)
                .openapi({
                  description: 'Name of the broadcast tournament.\n\nExample: `Sinquefield Cup`\n',
                }),
              info: BroadcastTourInfoSchema.exactOptional(),
              markdown: z
                .string()
                .max(20000)
                .exactOptional()
                .openapi({
                  description:
                    'Optional long description of the broadcast. Markdown is supported.\n',
                }),
              showScores: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(false)
                .exactOptional()
                .openapi({ description: 'Show players scores based on game results\n' }),
              showRatingDiffs: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(false)
                .exactOptional()
                .openapi({ description: "Show player's rating diffs\n" }),
              teamTable: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Show a team leaderboard. Requires WhiteTeam and BlackTeam PGN tags.\n',
                }),
              visibility: z
                .enum(['public', 'unlisted', 'private'])
                .default('public')
                .exactOptional()
                .openapi({
                  description:
                    'Who can view the broadcast.\n* `public`: Default. Anyone can view the broadcast\n* `unlisted`: Only people with the link can view the broadcast\n* `private`: Only the broadcast owner(s) can view the broadcast\n',
                }),
              players: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Optional replace player names, ratings and titles.\n\nOne line per player, formatted as such:\n\n```txt\nplayer name / FIDE ID\n```\n\nExample:\n\n```txt\nMagnus Carlsen / 1503014\n```\n\nPlayer names ignore case and punctuation, and match all possible combinations of 2 words: "Jorge Rick Vito" will match "Jorge Rick", "jorge vito", "Rick, Vito", etc.\n\nIf the player is NM or WNM, you can:\n\n```txt\nplayer name / FIDE ID / title\n```\n\nAlternatively, you may set tags manually, like so:\n\n```txt\nplayer name / rating / title / new name\n```\n\nAll values are optional. Example:\n```txt\nMagnus Carlsen / 2863 / GM\nYouGotLittUp / 1890 / / Louis Litt\n```\n',
                }),
              teams: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Optional: assign players to teams\n\nOne line per player, formatted as such:\n```txt\nTeam name; Fide Id or Player name\n```\n\nExample:\n```txt\nTeam Cats ; 3408230\nTeam Dogs ; Scooby Doo\n```\n\nBy default the PGN tags WhiteTeam and BlackTeam are used.\n',
                }),
              tier: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.union([z.literal(3), z.literal(4), z.literal(5)]),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Optional, for Lichess admins only, used to feature on /broadcast.\n\n* `3` for Official: normal tier\n* `4` for Official: high tier\n* `5` for Official: best tier\n',
                }),
              tiebreaks: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(BroadcastTiebreakExtendedCodeSchema).max(5),
                )
                .exactOptional(),
              grouping: z
                .object({
                  info: z
                    .object({
                      name: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description: 'Name of the group',
                          example: 'Chess Olympiad | Open',
                        }),
                      tours: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            'A linebreak separated list of tournament IDs to group together.\n',
                          example: 'wYigbpXq\nM5YHvpOX\nq6ezoCXP\n',
                        }),
                    })
                    .exactOptional()
                    .openapi({ required: [] }),
                  scoreGroups: z
                    .preprocess(
                      (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                      z
                        .array(
                          z
                            .string()
                            .openapi({
                              description:
                                'A comma separated list of tournament IDs to group together for scoring purposes\nCannot overlap with other score groups.\nCan only use groups mentioned in `info.tours`.\n',
                              example: 'wYigbpXq,M5YHvpOX',
                            }),
                        )
                        .max(10),
                    )
                    .exactOptional()
                    .openapi({
                      description:
                        "This parameter is repeated with an index for each score group, like 'grouping.scoreGroups[0]=wYigbpXq,M5YHvpOX'",
                    }),
                })
                .exactOptional()
                .openapi({ description: 'Group this broadcast along with others\n', required: [] }),
            })
            .openapi({ required: ['name'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'The broadcast tournament was successfully edited.',
      content: {
        'application/json': {
          schema: OkSchema,
          examples: { default: BroadcastsUpdateBroadcastTournamentJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
    400: {
      description: 'The broadcast tournament update failed.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ OAuth2: ['study:write'] }],
})

export const postBroadcastBroadcastTournamentIdNewRoute = createRoute({
  method: 'post',
  path: '/broadcast/{broadcastTournamentId}/new',
  tags: ['Broadcasts'],
  summary: 'Create a broadcast round',
  description:
    'Create a new broadcast round to relay external games.\nThis endpoint accepts the same form data as the web form.\n\nChoose one between `syncUrl`, `syncUrls`, `syncIds` and `syncUsers`, if it is missing, the broadcast needs to be fed by [pushing PGN to it](#tag/broadcasts/POST/api/broadcast/round/{broadcastRoundId}/push)\n',
  operationId: 'broadcastRoundCreate',
  request: {
    params: z.object({
      broadcastTournamentId: z
        .string()
        .length(8)
        .openapi({
          param: {
            in: 'path',
            name: 'broadcastTournamentId',
            description: 'The broadcast tournament ID',
            required: true,
            schema: { type: 'string', minLength: 8, maxLength: 8 },
          },
        }),
    }),
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .xor([
              z
                .object({ name: BroadcastRoundFormNameSchema })
                .openapi({ title: 'send games via push', required: ['name'] }),
              z
                .object({
                  name: BroadcastRoundFormNameSchema,
                  syncUrl: z
                    .url()
                    .openapi({
                      description:
                        'URL that Lichess will poll to get updates about the games. It must be publicly accessible from the Internet.\n\nExample:\n```txt\nhttps://myserver.org/myevent/round-10/games.pgn\n```\n',
                    }),
                  onlyRound: z
                    .preprocess(
                      (val) =>
                        typeof val === 'string' &&
                        /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                        (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                          ? Number(val)
                          : val,
                      z.int().min(1).max(999),
                    )
                    .exactOptional()
                    .openapi({
                      description:
                        'Filter games by round number\n\nOptional, only keep games from the source that match a round number.\nIt uses the PGN **Round** tag. These would match round 3:\n```txt\n[Round "3"]\n[Round "3.1"]\n```\nIf you set a round number, then games without a **Round** tag are dropped.\n\nIt only works if you chose `syncUrl` or `syncUrls` as the source.\n',
                    }),
                  slices: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'Select slices of the games\n\nOptional. Select games based on their position in the source.\n```txt\n1           only select the first board\n1-4         only select the first 4 boards\n1,2,3,4     same as above, first 4 boards\n11-15,21-25 boards 11 to 15, and boards 21 to 25\n2,3,7-9     boards 2, 3, 7, 8, and 9\n```\nSlicing is done after filtering by round number.\n\nIt only works if you chose `syncUrl` or `syncUrls` as the source.\n',
                    }),
                })
                .openapi({ title: 'retrieve games via PGN url', required: ['name', 'syncUrl'] }),
              z
                .object({
                  name: BroadcastRoundFormNameSchema,
                  syncUrls: z
                    .string()
                    .openapi({
                      description:
                        'URLs that Lichess will poll to get updates about the games, separated by newlines. They must be publicly accessible from the Internet.\n\nExample:\n```txt\nhttps://myserver.org/myevent/round-10/game-1.pgn\nhttps://myserver.org/myevent/round-10/game-2.pgn\n```\n',
                    }),
                  onlyRound: z
                    .preprocess(
                      (val) =>
                        typeof val === 'string' &&
                        /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                        (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                          ? Number(val)
                          : val,
                      z.int().min(1).max(999),
                    )
                    .exactOptional()
                    .openapi({
                      description:
                        'Filter games by round number\n\nOptional, only keep games from the source that match a round number.\nIt uses the PGN **Round** tag. These would match round 3:\n```txt\n[Round "3"]\n[Round "3.1"]\n```\nIf you set a round number, then games without a **Round** tag are dropped.\n\nIt only works if you chose `syncUrl` or `syncUrls` as the source.\n',
                    }),
                  slices: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'Select slices of the games\n\nOptional. Select games based on their position in the source.\n```txt\n1           only select the first board\n1-4         only select the first 4 boards\n1,2,3,4     same as above, first 4 boards\n11-15,21-25 boards 11 to 15, and boards 21 to 25\n2,3,7-9     boards 2, 3, 7, 8, and 9\n```\nSlicing is done after filtering by round number.\n\nIt only works if you chose `syncUrl` or `syncUrls` as the source.\n',
                    }),
                })
                .openapi({
                  title: 'retrieve games via mutiple PGN urls',
                  required: ['name', 'syncUrls'],
                }),
              z
                .object({
                  name: BroadcastRoundFormNameSchema,
                  syncIds: z
                    .string()
                    .openapi({
                      description:
                        'Lichess game IDs - Up to 100 Lichess game IDs, separated by spaces.\n',
                    }),
                })
                .openapi({
                  title: 'retrieve games via Lichess game IDs',
                  required: ['name', 'syncIds'],
                }),
              z
                .object({
                  name: BroadcastRoundFormNameSchema,
                  syncUsers: z
                    .string()
                    .openapi({ description: 'Up to 100 Lichess usernames, separated by spaces\n' }),
                })
                .openapi({
                  title: 'retrieve games via Lichess usernames',
                  required: ['name', 'syncUsers'],
                }),
            ])
            .and(
              z
                .object({
                  syncSource: z
                    .enum(['push', 'url', 'urls', 'ids', 'users'])
                    .default('push')
                    .exactOptional()
                    .openapi({ description: 'Where the games come from.\n' }),
                  startsAt: z
                    .preprocess((val) => {
                      if (
                        typeof val !== 'string' ||
                        !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val)
                      )
                        return val
                      if (/^-?\d+$/.test(val)) return BigInt(val)
                      const num = Number(val)
                      return Number.isSafeInteger(num) ? BigInt(num) : val
                    }, z.int64().min(1356998400070n))
                    .exactOptional()
                    .openapi({
                      type: 'integer',
                      format: 'int64',
                      minimum: 1356998400070,
                      description:
                        'Timestamp in milliseconds of broadcast round start. Leave empty to manually start the broadcast round.\nExample: `1356998400070`\n',
                    }),
                  startsAfterPrevious: z
                    .preprocess(
                      ((read) => (val: unknown) => {
                        const result = read.safeParse(val)
                        return result.success ? result.data : val
                      })(z.stringbool()),
                      z.boolean(),
                    )
                    .default(false)
                    .exactOptional()
                    .openapi({
                      description:
                        'The start date is unknown, and the round will start automatically when the previous round completes.\n',
                    }),
                  delay: z
                    .preprocess(
                      (val) =>
                        typeof val === 'string' &&
                        /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                        (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                          ? Number(val)
                          : val,
                      z.int().min(0).max(3600),
                    )
                    .exactOptional()
                    .openapi({
                      description:
                        "Delay in seconds for movements to appear on the broadcast. Leave it empty if you don't need it.\nExample: `900` (15 min)\n",
                    }),
                  status: z
                    .enum(['new', 'started', 'finished'])
                    .default('new')
                    .exactOptional()
                    .openapi({
                      description:
                        'Lichess can usually detect the round status, but you can also set it manually if needed.\n',
                    }),
                  rated: z
                    .preprocess(
                      ((read) => (val: unknown) => {
                        const result = read.safeParse(val)
                        return result.success ? result.data : val
                      })(z.stringbool()),
                      z.boolean(),
                    )
                    .default(true)
                    .exactOptional()
                    .openapi({
                      description:
                        "Whether the round is used when calculating players' rating changes.",
                    }),
                  customScoring: z
                    .object({
                      white: z
                        .object({
                          win: z.preprocess(
                            (val) =>
                              typeof val === 'string' &&
                              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                ? Number(val)
                                : val,
                            BroadcastCustomPointsSchema,
                          ),
                          draw: z.preprocess(
                            (val) =>
                              typeof val === 'string' &&
                              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                ? Number(val)
                                : val,
                            BroadcastCustomPointsSchema,
                          ),
                        })
                        .openapi({ required: ['win', 'draw'] }),
                      black: z
                        .object({
                          win: z.preprocess(
                            (val) =>
                              typeof val === 'string' &&
                              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                ? Number(val)
                                : val,
                            BroadcastCustomPointsSchema,
                          ),
                          draw: z.preprocess(
                            (val) =>
                              typeof val === 'string' &&
                              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                ? Number(val)
                                : val,
                            BroadcastCustomPointsSchema,
                          ),
                        })
                        .openapi({ required: ['win', 'draw'] }),
                    })
                    .exactOptional()
                    .openapi({
                      description: 'Scoring overrides for wins or draws.',
                      required: ['white', 'black'],
                    }),
                  teamCustomScoring: z
                    .object({
                      win: z.preprocess(
                        (val) =>
                          typeof val === 'string' &&
                          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                            ? Number(val)
                            : val,
                        BroadcastCustomPointsSchema,
                      ),
                      draw: z.preprocess(
                        (val) =>
                          typeof val === 'string' &&
                          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                            ? Number(val)
                            : val,
                        BroadcastCustomPointsSchema,
                      ),
                    })
                    .exactOptional()
                    .openapi({ required: ['win', 'draw'] }),
                  period: z
                    .preprocess(
                      (val) =>
                        typeof val === 'string' &&
                        /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                        (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                          ? Number(val)
                          : val,
                      z.int().min(2).max(60),
                    )
                    .exactOptional()
                    .openapi({ description: '(Only for Admins) Waiting time for each poll.\n' }),
                })
                .openapi({ required: [] }),
            ),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'The broadcast round was successfully created.',
      content: {
        'application/json': {
          schema: BroadcastRoundNewSchema,
          examples: { default: BroadcastsCreateBroadcastRoundJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
    400: {
      description: 'The creation of the broadcast failed.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ OAuth2: ['study:write'] }],
})

