export const getApiStreamBroadcastRoundBroadcastRoundIdPgnRoute = createRoute({
  method: 'get',
  path: '/api/stream/broadcast/round/{broadcastRoundId}.pgn',
  tags: ['Broadcasts'],
  summary: 'Stream an ongoing broadcast round as PGN',
  description:
    'This streaming endpoint first sends all games of a broadcast round in PGN format.\nThen, it waits for new moves to be played. As soon as it happens, the entire PGN of the game is sent to the stream.\nThe stream will also send PGNs when games are added to the round.\nThis is the best way to get updates about an ongoing round. Streaming means no polling,\nand no pollings means no latency, and minimum impact on the server.\n',
  operationId: 'broadcastStreamRoundPgn',
  request: {
    params: z.object({
      broadcastRoundId: z
        .string()
        .length(8)
        .openapi({
          param: {
            in: 'path',
            name: 'broadcastRoundId',
            description: 'The broadcast round ID',
            required: true,
            schema: { type: 'string', minLength: 8, maxLength: 8 },
          },
        }),
    }),
    query: z.object({
      clocks: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'clocks',
            description:
              'Include clock comments in the PGN moves, when available.\nExample: `2. exd5 { [%clk 1:01:27] } e5 { [%clk 1:01:28] }`\n',
            schema: { type: 'boolean', default: true },
            required: false,
          },
        }),
      comments: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'comments',
            description:
              'Include analysis comments in the PGN moves, when available.\nExample: `12. Bxf6 { [%eval 0.23] }`\n',
            schema: { type: 'boolean', default: true },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'The PGN representation of the round games, then the PGNs of games as they are updated.',
      content: {
        'application/x-chess-pgn': {
          schema: BroadcastPgnSchema,
          examples: { pgn: BroadcastsStreamOngoingBroadcastRoundAsPgnPgnExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
  },
  security: [{ OAuth2: ['study:read'] }],
})

