export const getApiBroadcastBroadcastTournamentIdPgnRoute = createRoute({
  method: 'get',
  path: '/api/broadcast/{broadcastTournamentId}.pgn',
  tags: ['Broadcasts'],
  summary: 'Export all rounds as PGN',
  description:
    'Download all games of all rounds of a broadcast in PGN format.\nIf a `study:read` [OAuth token](#tag/OAuth) is provided,\nthe private rounds where the user is a contributor will be available.\nYou may want to [download only the games of a single round](#tag/broadcasts/GET/api/broadcast/round/{broadcastRoundId}.pgn) instead.\n\nTo get real-time updates about an ongoing tournament, please use the \n[round PGN stream](#tag/broadcasts/GET/api/stream/broadcast/round/{broadcastRoundId}.pgn) or\n[tournament PGN stream](#tag/broadcasts/GET/api/stream/broadcast/tournament/{broadcastTournamentId}.pgn) or\n[group PGN stream](#tag/broadcasts/GET/api/stream/broadcast/group/{broadcastGroupId}.pgn) endpoints instead.\n',
  operationId: 'broadcastAllRoundsPgn',
  request: {
    params: z.object({
      broadcastTournamentId: z
        .string()
        .length(8)
        .openapi({
          param: {
            in: 'path',
            name: 'broadcastTournamentId',
            description: 'The broadcast tournament ID',
            required: true,
            schema: { type: 'string', minLength: 8, maxLength: 8 },
          },
        }),
    }),
    query: z.object({
      clocks: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'clocks',
            description:
              'Include clock comments in the PGN moves, when available.\nExample: `2. exd5 { [%clk 1:01:27] } e5 { [%clk 1:01:28] }`\n',
            schema: { type: 'boolean', default: true },
            required: false,
          },
        }),
      comments: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'comments',
            description:
              'Include analysis comments in the PGN moves, when available.\nExample: `12. Bxf6 { [%eval 0.23] }`\n',
            schema: { type: 'boolean', default: true },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The PGN representation of the broadcast.',
      content: {
        'application/x-chess-pgn': {
          schema: BroadcastPgnSchema,
          examples: { pgn: BroadcastsExportAllRoundsAsPgnPgnExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
  },
  security: [{ OAuth2: ['study:read'] }],
})

export const getApiBroadcastMyRoundsRoute = createRoute({
  method: 'get',
  path: '/api/broadcast/my-rounds',
  tags: ['Broadcasts'],
  summary: 'Get your broadcast rounds',
  description:
    "Stream all broadcast rounds you are a member of.\nAlso includes broadcasts rounds you did not create, but were invited to.\nAlso includes broadcasts rounds where you're a non-writing member. See the `writeable` flag in the response.\nRounds are ordered by rank, which is roughly chronological, most recent first, slightly pondered with popularity.\n",
  operationId: 'broadcastMyRoundsGet',
  request: {
    query: z.object({
      nb: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'nb',
            description: 'How many rounds to get',
            schema: { type: 'integer', minimum: 1, example: 20 },
            required: false,
          },
          example: 20,
        }),
    }),
  },
  responses: {
    200: {
      description: 'The broadcast rounds with their tournament and a `study.writeable` flag.',
      content: {
        'application/x-ndjson': {
          schema: BroadcastMyRoundSchema,
          examples: { default: BroadcastsGetYourBroadcastRoundsJsonExample },
        },
      },
    },
  },
  security: [{ OAuth2: ['study:read'] }],
})

