export const getApiTeamTeamIdUsersRoute = createRoute({
  method: 'get',
  path: '/api/team/{teamId}/users',
  tags: ['Teams'],
  summary: 'Get members of a team',
  description:
    'Members are sorted by reverse chronological order of joining the team (most recent first).\nOAuth is only required if the list of members is private.\nUp to 5,000 users are streamed as [ndjson](#description/streaming-with-nd-json).\n',
  operationId: 'teamIdUsers',
  request: {
    params: z.object({
      teamId: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'teamId',
            schema: { type: 'string', example: 'coders' },
            required: true,
          },
          example: 'coders',
        }),
    }),
    query: z.object({
      full: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'full',
            description:
              'Full user documents with performance ratings.\nThis limits the response to 1,000 users.\n',
            schema: { type: 'boolean', default: false },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The list of users in the team.',
      content: {
        'application/x-ndjson': {
          schema: z
            .object({
              joinedTeamAt: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .exactOptional()
                .openapi({ type: 'integer', format: 'int64' }),
              id: z.string(),
              name: z.string(),
              flair: FlairSchema.exactOptional(),
              title: TitleSchema.exactOptional(),
              patron: PatronSchema.exactOptional(),
              patronColor: PatronColorSchema.exactOptional(),
              url: z.url().exactOptional(),
            })
            .openapi({ required: ['id', 'name'] }),
          examples: { default: TeamsGetMembersOfTeamJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
  },
  security: [{ OAuth2: ['team:read'] }],
})

