export const getTeamUpdatesRoute = createRoute({
  method: 'get',
  path: '/team/updates',
  tags: ['Teams'],
  summary: 'Get updates from your teams',
  description:
    'Paginator of the most recent updates posted by team leaders of teams you have joined.\n',
  operationId: 'teamUpdates',
  request: {
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'page',
            schema: { type: 'integer', example: 1, default: 1 },
            required: false,
          },
          example: 1,
        }),
    }),
  },
  responses: {
    200: {
      description: 'A paginated list of team updates',
      content: {
        'application/json': {
          schema: TeamUpdatesSchema,
          examples: { default: TeamsUpdatesJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
  },
  security: [{ OAuth2: ['team:read'] }],
})

