export const getApiStreamEventRoute = createRoute({
  method: 'get',
  path: '/api/stream/event',
  tags: ['Board', 'Bot'],
  summary: 'Stream incoming events',
  description:
    'Stream the events reaching a lichess user in real time as [ndjson](#description/streaming-with-nd-json).\n\nAn empty line is sent every 7 seconds for keep alive purposes.\n\nEach non-empty line is a JSON object containing a `type` field. Possible values are:\n- `gameStart` Start of a game\n- `gameFinish` Completion of a game\n- `challenge` A player sends you a challenge or you challenge someone\n- `challengeCanceled` A player cancels their challenge to you\n- `challengeDeclined` The opponent declines your challenge\n\nWhen the stream opens, all current challenges and games are sent.\n\nOnly one global event stream can be active at a time. When the stream opens, the previous one with the same access token is closed.\n',
  operationId: 'apiStreamEvent',
  responses: {
    200: {
      description: 'The stream of events reaching the logged in user.',
      content: {
        'application/x-ndjson': {
          schema: z.xor([
            GameStartEventSchema,
            GameFinishEventSchema,
            ChallengeEventSchema,
            ChallengeCanceledEventSchema,
            ChallengeDeclinedEventSchema,
          ]),
          examples: {
            GameStartEvent: StreamGameStartJsonExample,
            'GameStartEvent (vs AI)': StreamGameStartAiJsonExample,
            GameFinishEvent: StreamGameFinishJsonExample,
            'GameFinishEvent (vs AI)': StreamGameFinishAiJsonExample,
            ChallengeEvent: StreamChallengeJsonExample,
            ChallengeDeclinedEvent: StreamChallengeDeclinedJsonExample,
            ChallengeCanceledEvent: StreamChallengeCanceledJsonExample,
          },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
  },
  security: [{ OAuth2: ['challenge:read', 'bot:play', 'board:play'] }],
})

export const postApiBoardSeekRoute = createRoute({
  method: 'post',
  path: '/api/board/seek',
  tags: ['Board'],
  summary: 'Create a seek',
  description:
    "Create a public seek, to start a game with a random player.\n\n### Real-time seek\n\nSpecify the `time` and `increment` clock values.\nThe response is streamed but doesn't contain any information.\n\n**Keep the connection open to keep the seek active**.\n\nIf the client closes the connection, the seek is canceled. This way, if the client terminates, the user won't be paired in a game they wouldn't play.\nWhen the seek is accepted, or expires, the server closes the connection.\n\n**Make sure to also have an [Event stream](#tag/board/GET/api/board/game/stream/{gameId}) open**, to be notified when a game starts.\nWe recommend opening the [Event stream](#tag/board/GET/api/board/game/stream/{gameId}) first, then the seek stream. This way,\nyou won't miss the game event if the seek is accepted immediately.\n\n### Correspondence seek\n\nSpecify the `days` per turn value.\nThe response is not streamed, it immediately completes with the seek ID. The seek remains active on the server until it is joined by someone.\n",
  operationId: 'apiBoardSeek',
  request: {
    body: {
      description: 'Parameters of the seek',
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              rated: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(false)
                .exactOptional()
                .openapi({
                  description: 'Whether the game is rated and impacts players ratings.',
                  example: true,
                }),
              variant: VariantKeySchema.exactOptional(),
              ratingRange: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The rating range of potential opponents. Better left empty.\nExample: 1500-1800\n',
                }),
            })
            .openapi({ required: [] })
            .and(
              z.xor([
                z
                  .object({
                    time: z
                      .preprocess(
                        (val) =>
                          typeof val === 'string' &&
                          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                            ? Number(val)
                            : val,
                        z.number().min(0).max(180),
                      )
                      .openapi({
                        description: 'Clock initial time in minutes. Required for real-time seeks.',
                        example: 15,
                      }),
                    increment: z
                      .preprocess(
                        (val) =>
                          typeof val === 'string' &&
                          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                            ? Number(val)
                            : val,
                        z.int().min(0).max(180),
                      )
                      .openapi({
                        description: 'Clock increment in seconds. Required for real-time seeks.',
                        example: 15,
                      }),
                    color: ChallengeColorSchema.exactOptional().openapi({
                      description:
                        'The color to play. Better left empty to automatically get 50% white.',
                    }),
                  })
                  .openapi({ title: 'real-time', required: ['time', 'increment'] }),
                z
                  .object({
                    days: z
                      .preprocess(
                        (val) =>
                          typeof val === 'string' &&
                          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                            ? Number(val)
                            : val,
                        z.union([
                          z.literal(1),
                          z.literal(2),
                          z.literal(3),
                          z.literal(5),
                          z.literal(7),
                          z.literal(10),
                          z.literal(14),
                        ]),
                      )
                      .openapi({
                        description: 'Days per turn. Required for correspondence seeks.',
                      }),
                  })
                  .openapi({ title: 'correspondence', required: ['days'] }),
              ]),
            ),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'The seek was successfully created.',
      content: {
        'application/json': {
          schema: z
            .object({ id: z.string() })
            .openapi({
              description: 'Only happens when doing a correspondence seek.',
              required: ['id'],
            }),
          examples: { default: BoardCreateCorrespondenceSeekJsonExample },
        },
        'application/x-ndjson': {
          schema: z
            .literal('')
            .openapi({
              description:
                'Only happens when doing a real-time seek.\n\nA periodic empty line until the seek is accepted by another player,\nat which point the connection closes and no data is sent.\n',
            }),
          examples: { default: BoardCreateRealTimeSeekJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
    400: {
      description: 'The creation of the seek failed.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ OAuth2: ['board:play'] }],
})

export const getApiBoardGameStreamGameIdRoute = createRoute({
  method: 'get',
  path: '/api/board/game/stream/{gameId}',
  tags: ['Board'],
  summary: 'Stream Board game state',
  description:
    'Stream the state of a game being played with the Board API, as [ndjson](#description/streaming-with-nd-json).\n\nUse this endpoint to get updates about the game in real-time, with a single request.\n\nEach line is a JSON object containing a `type` field. Possible values are:\n  - `gameFull` Full game data. All values are immutable, except for the `state` field.\n  - `gameState` Current state of the game. Immutable values not included. Sent when a move is played, a draw is offered, or when the game ends.\n  - `chatLine` Chat message sent by a user in the `room` "player" or "spectator".\n  - `opponentGone` Whether the opponent has left the game, and how long before you can claim a win or draw.\n\nThe first line is always of type `gameFull`.\n\nThe server closes the stream when the game ends, or if the game has already ended.\n',
  operationId: 'boardGameStream',
  request: {
    params: z.object({
      gameId: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'gameId',
            schema: { type: 'string', example: '5IrD6Gzz' },
            required: true,
          },
          example: '5IrD6Gzz',
        }),
    }),
  },
  responses: {
    200: {
      description: 'The stream of the game.',
      content: {
        'application/x-ndjson': {
          schema: z.xor([
            GameFullEventSchema,
            GameStateEventSchema,
            ChatLineEventSchema,
            OpponentGoneEventSchema,
          ]),
          examples: {
            'game full': BoardStreamBoardGameStateGameFullJsonExample,
            'game state': BoardStreamBoardGameStateGameStateJsonExample,
            'chat line': BoardStreamBoardGameStateChatLineJsonExample,
            'opponent gone': BoardStreamBoardGameStateOpponentGoneJsonExample,
          },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
    404: {
      description: 'The game was not found.',
      content: { 'application/json': { schema: NotFoundSchema } },
    },
  },
  security: [{ OAuth2: ['board:play'] }],
})

