export const postApiBoardGameGameIdDrawAcceptRoute = createRoute({
  method: 'post',
  path: '/api/board/game/{gameId}/draw/{accept}',
  tags: ['Board'],
  summary: 'Handle draw offers',
  description:
    "Create/accept/decline draw offers.\n- `yes`: Offer a draw, or accept the opponent's draw offer.\n- `no`: Decline a draw offer from the opponent.\n",
  operationId: 'boardGameDraw',
  request: {
    params: z.object({
      gameId: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'gameId',
            schema: { type: 'string', example: '5IrD6Gzz' },
            required: true,
          },
          example: '5IrD6Gzz',
        }),
      accept: ((schema) =>
        z.union([
          z.preprocess(
            ((read) => (val: unknown) => {
              const result = read.safeParse(val)
              return result.success ? result.data : val
            })(z.stringbool()),
            schema,
          ),
          schema,
        ]))(z.union([z.boolean(), z.literal('yes')])).openapi({
        param: {
          in: 'path',
          name: 'accept',
          schema: {
            anyOf: [{ type: 'boolean' }, { type: 'string', const: 'yes' }],
            example: 'yes',
          },
          required: true,
        },
        example: 'yes',
      }),
    }),
  },
  responses: {
    200: {
      description: 'The draw offer was successfully sent.',
      content: {
        'application/json': {
          schema: OkSchema,
          examples: { default: BoardHandleDrawOfferJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
    400: {
      description: 'The draw offering failed.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ OAuth2: ['board:play'] }],
})

