export const postApiChallengeUsernameRoute = createRoute({
  method: 'post',
  path: '/api/challenge/{username}',
  tags: ['Challenges'],
  summary: 'Create a challenge',
  description:
    'Challenge someone to play. The targeted player can choose to accept or decline.\nIf the challenge is accepted, you will be notified on the [event stream](#tag/board/GET/api/board/game/stream/{gameId})\nthat a new game has started. The game ID will be the same as the challenge ID.\nChallenges for realtime games (not correspondence) expire after 20s if not accepted.\nTo prevent that, use the `keepAliveStream` flag described below.\n',
  operationId: 'challengeCreate',
  request: {
    params: z.object({
      username: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'username',
            schema: { type: 'string', example: 'LeelaChess' },
            required: true,
          },
          example: 'LeelaChess',
        }),
    }),
    body: {
      description: 'Parameters of the challenge',
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .xor([
              z
                .object({
                  'clock.limit': z
                    .preprocess(
                      (val) =>
                        typeof val === 'string' &&
                        /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                        (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                          ? Number(val)
                          : val,
                      z.int().min(0).max(10800),
                    )
                    .openapi({
                      description:
                        'Clock initial time in seconds. If empty, a correspondence game is created. Valid values are 0, 15, 30, 45, 60, 90, and any multiple of 60 up to 10800 (3 hours).',
                      example: 300,
                    }),
                  'clock.increment': z
                    .preprocess(
                      (val) =>
                        typeof val === 'string' &&
                        /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                        (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                          ? Number(val)
                          : val,
                      z.int().min(0).max(60),
                    )
                    .openapi({
                      description:
                        'Clock increment in seconds. If empty, a correspondence game is created.',
                      example: 1,
                    }),
                })
                .openapi({ title: 'real-time', required: ['clock.limit', 'clock.increment'] }),
              z
                .object({
                  days: z
                    .preprocess(
                      (val) =>
                        typeof val === 'string' &&
                        /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                        (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                          ? Number(val)
                          : val,
                      z.union([
                        z.literal(1),
                        z.literal(2),
                        z.literal(3),
                        z.literal(5),
                        z.literal(7),
                        z.literal(10),
                        z.literal(14),
                      ]),
                    )
                    .openapi({
                      description:
                        'Days per move, for correspondence games. Clock settings must be omitted.',
                    }),
                })
                .openapi({ title: 'correspondence', required: ['days'] }),
              z.object({}).openapi({ title: 'unlimited' }),
            ])
            .and(
              z
                .object({
                  rated: z
                    .preprocess(
                      ((read) => (val: unknown) => {
                        const result = read.safeParse(val)
                        return result.success ? result.data : val
                      })(z.stringbool()),
                      z.boolean(),
                    )
                    .default(false)
                    .exactOptional()
                    .openapi({ description: 'Game is rated and impacts players ratings' }),
                  color: ChallengeColorSchema.default('random')
                    .exactOptional()
                    .openapi({ description: 'Which color you get to play' }),
                  variant: VariantKeySchema.exactOptional(),
                  fen: FromPositionFENSchema.exactOptional(),
                  keepAliveStream: z
                    .preprocess(
                      ((read) => (val: unknown) => {
                        const result = read.safeParse(val)
                        return result.success ? result.data : val
                      })(z.stringbool()),
                      z.boolean(),
                    )
                    .exactOptional()
                    .openapi({
                      description:
                        'If set, the response is streamed as [ndjson](#description/streaming-with-nd-json).\nThe challenge is kept alive until the connection is closed by the client.\nWhen the challenge is accepted, declined or canceled, a message of the form `{"done":"accepted"}` is sent,\nthen the connection is closed by the server.\nIf not set, the response is not streamed, and the challenge expires after 20s if not accepted.\n',
                    }),
                  rules: z
                    .enum(['noAbort', 'noRematch', 'noGiveTime', 'noClaimWin', 'noEarlyDraw'])
                    .exactOptional()
                    .openapi({
                      description:
                        'Extra game rules separated by commas.\nExample: `noAbort,noRematch`\n',
                    }),
                })
                .openapi({ required: [] }),
            ),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'The challenge was successfully created.',
      content: {
        'application/json': {
          schema: ChallengeJsonSchema,
          examples: { default: ChallengesCreateChallengeJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
    400: {
      description: 'The creation of the challenge failed.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ OAuth2: ['challenge:write', 'bot:play', 'board:play'] }],
})

