export const postApiChallengeAiRoute = createRoute({
  method: 'post',
  path: '/api/challenge/ai',
  tags: ['Challenges'],
  summary: 'Challenge the AI',
  description:
    'Start a game with Lichess AI.\nYou will be notified on the [event stream](#tag/board/GET/api/board/game/stream/{gameId}) that a new game has started.\n',
  operationId: 'challengeAi',
  request: {
    body: {
      description: 'Parameters of the game',
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              level: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(1).max(8),
                )
                .openapi({ description: 'AI strength' }),
              'clock.limit': z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(0).max(10800),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Clock initial time in seconds. If empty, a correspondence game is created.',
                  example: 300,
                }),
              'clock.increment': z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(0).max(60),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Clock increment in seconds. If empty, a correspondence game is created.',
                  example: 1,
                }),
              days: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.union([
                    z.literal(1),
                    z.literal(2),
                    z.literal(3),
                    z.literal(5),
                    z.literal(7),
                    z.literal(10),
                    z.literal(14),
                  ]),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Days per move, for correspondence games. Clock settings must be omitted.',
                }),
              color: ChallengeColorSchema.default('random')
                .exactOptional()
                .openapi({ description: 'Which color you get to play' }),
              variant: VariantKeySchema.exactOptional(),
              fen: FromPositionFENSchema.exactOptional(),
            })
            .openapi({ required: ['level'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'The game with Lichess AI was successfully started.',
      content: {
        'application/json': {
          schema: z
            .object({
              id: z.string().length(8).exactOptional(),
              variant: VariantSchema.exactOptional(),
              speed: SpeedSchema.exactOptional(),
              perf: PerfTypeSchema.exactOptional(),
              rated: z.boolean().exactOptional(),
              fen: z.string().exactOptional(),
              turns: z.int().exactOptional(),
              source: GameSourceSchema.exactOptional(),
              status: GameStatusSchema.exactOptional(),
              createdAt: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .exactOptional()
                .openapi({ type: 'integer', format: 'int64' }),
              player: GameColorSchema.exactOptional(),
              fullId: z.string().length(12).exactOptional(),
            })
            .openapi({ required: [] }),
          examples: { default: ChallengesChallengeAiJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
    400: {
      description: 'The creation of a game with Lichess AI failed.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ OAuth2: ['challenge:write', 'bot:play', 'board:play'] }],
})

export const postApiChallengeOpenRoute = createRoute({
  method: 'post',
  path: '/api/challenge/open',
  tags: ['Challenges'],
  summary: 'Open-ended challenge',
  description:
    'Create a challenge that any 2 players can join.\nShare the URL of the challenge. the first 2 players to click it will be paired for a game.\nThe response body also contains `whiteUrl` and `blackUrl`.\nYou can control which color each player gets by giving them these URLs,\ninstead of the main challenge URL.\nOpen challenges expire after 24h.\nIf the challenge creation is [authenticated with OAuth2](#description/authentication),\nthen you can use the [challenge cancel endpoint](#tag/challenges/POST/api/challenge/{challengeId}/cancel) to cancel it.\nTo directly pair 2 known players, use [this endpoint](#tag/bulk-pairings/GET/api/bulk-pairing) instead.\n',
  operationId: 'challengeOpen',
  request: {
    body: {
      description: 'Parameters of the game',
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              rated: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(false)
                .exactOptional()
                .openapi({ description: 'Game is rated and impacts players ratings' }),
              'clock.limit': z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(0).max(10800),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Clock initial time in seconds. If empty, a correspondence game is created.',
                  example: 300,
                }),
              'clock.increment': z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(0).max(60),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Clock increment in seconds. If empty, a correspondence game is created.',
                  example: 1,
                }),
              days: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.union([
                    z.literal(1),
                    z.literal(2),
                    z.literal(3),
                    z.literal(5),
                    z.literal(7),
                    z.literal(10),
                    z.literal(14),
                  ]),
                )
                .exactOptional()
                .openapi({ description: 'Days per turn. For correspondence challenges.' }),
              variant: VariantKeySchema.exactOptional(),
              fen: FromPositionFENSchema.exactOptional(),
              name: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Optional name for the challenge, that players will see on the challenge page.',
                }),
              rules: z
                .enum(['noRematch', 'noGiveTime', 'noClaimWin', 'noEarlyDraw', 'noAbort'])
                .exactOptional()
                .openapi({
                  description:
                    'Extra game rules separated by commas.\nExample: `noRematch,noGiveTime`\nThe `noAbort` rule is available for Lichess admins only\n',
                }),
              users: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Optional pair of usernames, separated by a comma.\nIf set, only these users will be allowed to join the game.\nThe first username gets the white pieces.\nExample: `Username1,Username2`\n',
                }),
              expiresAt: z
                .preprocess((val) => {
                  if (
                    typeof val !== 'string' ||
                    !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val)
                  )
                    return val
                  if (/^-?\d+$/.test(val)) return BigInt(val)
                  const num = Number(val)
                  return Number.isSafeInteger(num) ? BigInt(num) : val
                }, z.int64())
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description:
                    "Timestamp in milliseconds to expire the challenge. Defaults to 24h after creation. Can't be more than 2 weeks after creation.",
                }),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'The challenge was successfully created.',
      content: {
        'application/json': {
          schema: ChallengeOpenJsonSchema,
          examples: { default: ChallengesOpenEndedChallengeJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
    400: {
      description: 'The creation of the challenge failed.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [],
})

