export const postApiBulkPairingRoute = createRoute({
  method: 'post',
  path: '/api/bulk-pairing',
  tags: ['Bulk pairings'],
  summary: 'Create a bulk pairing',
  description:
    'Schedule many games at once, up to 24h in advance.\nOAuth tokens are required for all paired players, with the `challenge:write` scope.\nYou can schedule up to 500 games every 10 minutes. [Contact us](mailto:contact@lichess.org) if you need higher limits.\nIf games have a real-time clock, each player must have only one pairing.\nFor correspondence games, players can have multiple pairings within the same bulk.\n\n**The entire bulk is rejected if:**\n  - a token is missing\n  - a token is present more than once (except in correspondence)\n  - a token lacks the `challenge:write` scope\n  - a player account is closed\n  - a player is paired more than once (except in correspondence)\n  - a bulk is already scheduled to start at the same time with the same player\n  - you have 20 scheduled bulks\n  - you have 1000 scheduled games\n\nPartial bulks are never created. Either it all fails, or it all succeeds.\nWhen it fails, it does so with an error message explaining the issue.\nFailed bulks are not counted in the rate limiting, they are free.\nFix the issues, manually or programmatically, then retry to schedule the bulk.\nA successful bulk creation returns a JSON bulk document. Its ID can be used for further operations.\n',
  operationId: 'bulkPairingCreate',
  request: {
    body: {
      description: 'Parameters of the pairings',
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              players: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'OAuth tokens of all the players to pair, with the syntax `tokenOfWhitePlayerInGame1:tokenOfBlackPlayerInGame1,tokenOfWhitePlayerInGame2:tokenOfBlackPlayerInGame2,...`.\nThe 2 tokens of the players of a game are separated with `:`. The first token gets the white pieces. Games are separated with `,`.\nUp to 1000 tokens can be sent, for a max of 500 games.\nEach token must be included at most once.\nExample: `token1:token2,token3:token4,token5:token6`\n',
                }),
              'clock.limit': z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(0).max(10800),
                )
                .exactOptional()
                .openapi({ description: 'Clock initial time in seconds. Example: `600`\n' }),
              'clock.increment': z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(0).max(60),
                )
                .exactOptional()
                .openapi({ description: 'Clock increment in seconds. Example: `2`\n' }),
              days: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.union([
                    z.literal(1),
                    z.literal(2),
                    z.literal(3),
                    z.literal(5),
                    z.literal(7),
                    z.literal(10),
                    z.literal(14),
                  ]),
                )
                .exactOptional()
                .openapi({ description: 'Days per turn. For correspondence games only.' }),
              pairAt: z
                .preprocess((val) => {
                  if (
                    typeof val !== 'string' ||
                    !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val)
                  )
                    return val
                  if (/^-?\d+$/.test(val)) return BigInt(val)
                  const num = Number(val)
                  return Number.isSafeInteger(num) ? BigInt(num) : val
                }, z.int64())
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description:
                    'Date at which the games will be created as a Unix timestamp in milliseconds.\nUp to 7 days in the future.\nOmit, or set to current date and time, to start the games immediately.\nExample: `1612289869919`\n',
                }),
              startClocksAt: z
                .preprocess((val) => {
                  if (
                    typeof val !== 'string' ||
                    !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val)
                  )
                    return val
                  if (/^-?\d+$/.test(val)) return BigInt(val)
                  const num = Number(val)
                  return Number.isSafeInteger(num) ? BigInt(num) : val
                }, z.int64())
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description:
                    'Date at which the clocks will be automatically started as a Unix timestamp in milliseconds.\nUp to 7 days in the future.\nNote that the clocks can start earlier than specified, if players start making moves in the game.\nIf omitted, the clocks will not start automatically.\nExample: `1612289869919`\n',
                }),
              rated: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(false)
                .exactOptional()
                .openapi({ description: 'Game is rated and impacts players ratings' }),
              variant: VariantKeySchema.exactOptional(),
              fen: FromPositionFENSchema.exactOptional(),
              message: z
                .string()
                .default('Your game with {opponent} is ready: {game}.')
                .exactOptional()
                .openapi({
                  description:
                    'Message that will be sent to each player, when the game is created.  It is sent from your user account.\n`{opponent}` and `{game}` are placeholders that will be replaced with the opponent and the game URLs.\nYou can omit this field to send the default message,\nbut if you set your own message, it must at least contain the `{game}` placeholder.\nYou can also disable messages entirely, by setting the template to `{noMessage}`. You will then need to notify the players yourself about their games.\n',
                }),
              rules: z
                .enum(['noAbort', 'noRematch', 'noGiveTime', 'noClaimWin', 'noEarlyDraw'])
                .exactOptional()
                .openapi({
                  description:
                    'Extra game rules separated by commas.\nExample: `noAbort,noRematch`\n',
                }),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'The bulk pairing has been successfully created.',
      content: {
        'application/json': {
          schema: BulkPairingSchema,
          examples: { default: BulkPairingsCreateBulkPairingJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
    400: {
      description: 'The creation of the bulk pairings failed.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ OAuth2: ['challenge:bulk'] }],
})

