export const getApiCloudEvalRoute = createRoute({
  method: 'get',
  path: '/api/cloud-eval',
  tags: ['Analysis'],
  summary: 'Get cloud evaluation of a position.',
  description:
    'Get the cached evaluation of a position, if available.\nOpening positions have more chances of being available. There are about 320 million positions in the database.\nUp to 5 variations may be available. Variants are supported.\nUse this endpoint to fetch a few positions here and there.\nIf you want to download a lot of positions, [get the full list](https://database.lichess.org/#evals) from our exported database.\n',
  operationId: 'apiCloudEval',
  request: {
    query: z.object({
      fen: z
        .string()
        .openapi({
          param: {
            in: 'query',
            name: 'fen',
            required: true,
            description: 'X-FEN of the position',
            schema: { type: 'string' },
            example: 'r1bqkbnr/pppp1ppp/2n5/1B2p3/4P3/5N2/PPPP1PPP/RNBQK2R b KQkq - 3 3',
          },
        }),
      multiPv: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'multiPv',
            description: 'Number of variations',
            schema: { type: 'integer', default: 1 },
            required: false,
          },
        }),
      variant: VariantKeySchema.openapi({
        param: {
          in: 'query',
          name: 'variant',
          description: 'Variant',
          schema: { $ref: '#/components/schemas/VariantKey' },
          required: false,
        },
      }).exactOptional(),
    }),
  },
  responses: {
    200: {
      description: 'The evaluation of the position.',
      content: {
        'application/json': {
          schema: CloudEvalSchema,
          examples: { default: AnalysisGetCloudEvaluationJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
    404: {
      description: 'The position was not found in the cloud evaluation database.',
      content: {
        'application/json': {
          schema: z.object({ error: z.string().exactOptional() }).openapi({ required: [] }),
        },
      },
    },
  },
  security: [],
})

