export const postApiExternalEngineIdAnalyseRoute = createRoute({
  method: 'post',
  path: '/api/external-engine/{id}/analyse',
  tags: ['External engine'],
  summary: 'Analyse with external engine',
  description:
    '**Endpoint: `https://engine.lichess.ovh/api/external-engine/{id}/analyse`**\n\nRequest analysis from an external engine.\nResponse content is streamed as [newline delimited JSON](#description/streaming-with-nd-json).\nThe properties are based on the [UCI specification](https://backscattering.de/chess/uci/#engine).\nAnalysis stops when the client goes away, the requested limit\nis reached, or the provider goes away.\n',
  operationId: 'apiExternalEngineAnalyse',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'id',
            required: true,
            description: 'The external engine id.',
            schema: { type: 'string' },
            example: 'eei_aTKImBJOnv6j',
          },
        }),
    }),
    body: {
      description: 'Engine credentials and analysis request.',
      content: {
        'application/json': {
          schema: z
            .object({
              clientSecret: z.string().openapi({ example: 'ees_mdF2hK0hlKGSPeC6' }),
              work: ExternalEngineWorkSchema,
            })
            .openapi({ required: ['clientSecret', 'work'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Stream of analysis output',
      content: {
        'application/x-ndjson': {
          schema: z
            .object({
              time: z
                .int()
                .min(0)
                .openapi({ description: 'Number of milliseconds the search has been going on' }),
              depth: z.int().min(0).openapi({ description: 'Current search depth' }),
              nodes: z.int().min(0).openapi({ description: 'Number of nodes visited so far' }),
              pvs: z
                .array(
                  z
                    .object({
                      depth: z
                        .int()
                        .min(0)
                        .openapi({ description: 'Current search depth of the pv' }),
                      cp: z
                        .int()
                        .exactOptional()
                        .openapi({
                          description: "Evaluation in centi-pawns, from White's point of view",
                        }),
                      mate: z
                        .int()
                        .exactOptional()
                        .openapi({
                          description:
                            "Evaluation in signed moves to mate, from White's point of view",
                        }),
                      moves: z
                        .array(z.string())
                        .openapi({ description: 'Variation in UCI notation' }),
                    })
                    .openapi({ required: ['depth', 'moves'] }),
                )
                .openapi({
                  description: 'Information about up to 5 pvs, with the primary pv at index 0.',
                }),
            })
            .openapi({ required: ['time', 'depth', 'nodes', 'pvs'] }),
          examples: { default: ExternalEngineAnalyseWithExternalEngineJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
  },
  security: [],
  servers: [
    { url: 'https://engine.lichess.ovh' },
    { url: 'http://localhost:{port}', variables: { port: { default: '9666' } } },
  ],
})

