export const getOauthRoute = createRoute({
  method: 'get',
  path: '/oauth',
  tags: ['OAuth'],
  summary: 'Request authorization code',
  description:
    'OAuth2 authorization endpoint.\nStart the OAuth2 Authorization Code Flow with PKCE by securely\ngenerating two random strings unique to each authorization\nrequest:\n\n* `code_verifier`\n* `state`\n\nStore these in session storage. Make sure not to reveal `code_verifier`\nto eavesdroppers. Do not show it in URLs, do not abuse `state` to store\nit, do not send it over insecure connections. However it is fine if\nthe user themselves can extract `code_verifier`, which will always be\npossible for fully client-side apps.\nThen send the user to this endpoint. They will be prompted to grant\nauthorization and then be redirected back to the given `redirect_uri`.\nIf the authorization failed, the following query string parameters will\nbe appended to the redirection:\n\n* `error`, in particular with value `access_denied` if the user\n   cancelled authorization\n* `error_description` to aid debugging\n* `state`, exactly as passed in the `state` parameter\n\nIf the authorization succeeded, the following query string parameters\nwill be appended to the redirection:\n\n* `code`, containing a fresh short-lived authorization code\n* `state`, exactly as passed in the `state` parameter\n\nNext, to defend against cross site request forgery, check that the\nreturned `state` matches the `state` you originally generated.\n\nFinally, continue by using the authorization code to\n[obtain an access token](#tag/oauth/POST/api/token).\n',
  operationId: 'oauth',
  request: {
    query: z.object({
      response_type: z
        .literal('code')
        .openapi({
          param: {
            in: 'query',
            name: 'response_type',
            description: 'Must be `code`.',
            required: true,
            schema: { type: 'string', const: 'code' },
          },
        }),
      client_id: z
        .string()
        .openapi({
          param: {
            in: 'query',
            name: 'client_id',
            description: 'Arbitrary identifier that uniquely identifies your application.',
            example: 'example.com',
            required: true,
            schema: { type: 'string' },
          },
        }),
      redirect_uri: z
        .string()
        .openapi({
          param: {
            in: 'query',
            name: 'redirect_uri',
            description:
              'The absolute URL that the user should be redirected to with the authorization result.',
            required: true,
            schema: { type: 'string' },
          },
        }),
      code_challenge_method: z
        .literal('S256')
        .openapi({
          param: {
            in: 'query',
            name: 'code_challenge_method',
            description: 'Must be `S256`.',
            required: true,
            schema: { type: 'string', const: 'S256' },
          },
        }),
      code_challenge: z
        .string()
        .openapi({
          param: {
            in: 'query',
            name: 'code_challenge',
            description: 'Compute `BASE64URL(SHA256(code_verifier))`.',
            required: true,
            schema: { type: 'string' },
          },
        }),
      scope: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'scope',
            description: 'Space separated list of requested OAuth scopes, if any.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      username: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'username',
            description: 'Hint that you want the user to log in with a specific Lichess username.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      state: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'state',
            description:
              'Arbitrary state that will be returned verbatim with the authorization result.',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: { 200: { description: 'Authorization prompt will be displayed to the user.' } },
  security: [],
})

export const postApiTokenRoute = createRoute({
  method: 'post',
  path: '/api/token',
  tags: ['OAuth'],
  summary: 'Obtain access token',
  description: 'OAuth2 token endpoint. Exchanges an authorization code for an access token.\n',
  operationId: 'apiToken',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              grant_type: z
                .literal('authorization_code')
                .exactOptional()
                .openapi({ example: 'authorization_code' }),
              code: z
                .string()
                .exactOptional()
                .openapi({
                  example: 'liu_iS1uOZg99Htmo58ex2jKgYziUfzsnAl0',
                  description:
                    'The authorization code that was sent in the `code` parameter to your `redirect_uri`.',
                }),
              code_verifier: z
                .string()
                .exactOptional()
                .openapi({
                  example:
                    'Ry1rbGdOMTQtUjhOc0lmTnFKak1LTHV0NjlRMll2aXYtTThkQnlJRkRpaGwyQjh0ZDNFdzFPSG9KUlY4M1NrRzJ5ZHhUdjVZR08zLTZOT3dCN2xLfjZOXzU2WHk4SENP',
                  description:
                    'A `code_challenge` was used to request the authorization code. This must be the `code_verifier` it was derived from.',
                }),
              redirect_uri: z
                .string()
                .exactOptional()
                .openapi({
                  example: 'http://example.com/',
                  description:
                    'Must match the `redirect_uri` used to request the authorization code.',
                }),
              client_id: z
                .string()
                .exactOptional()
                .openapi({
                  example: 'example.com',
                  description: 'Must match the `client_id` used to request the authorization code.',
                }),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Access token successfully obtained.',
      content: {
        'application/json': {
          schema: z
            .object({ token_type: z.string(), access_token: z.string(), expires_in: z.int() })
            .openapi({ required: ['token_type', 'access_token', 'expires_in'] }),
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
    400: {
      description: 'Failed to obtain access token.',
      content: { 'application/json': { schema: OAuthErrorSchema } },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
  },
  security: [],
})

