export const postApiTokenTestRoute = createRoute({
  method: 'post',
  path: '/api/token/test',
  tags: ['OAuth'],
  summary: 'Test multiple OAuth tokens',
  description:
    'For up to 1000 OAuth tokens,\nreturns their associated user ID and scopes,\nor `null` if the token is invalid.\nThe method is `POST` so a longer list of tokens can be sent in the request body.\n',
  operationId: 'tokenTest',
  request: {
    body: {
      description: 'OAuth tokens separated by commas. Up to 1000.',
      content: {
        'text/plain': {
          schema: z.string(),
          examples: { body: OauthTestMultipleOauthTokensRequestTxtExample },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'The representation of the OAuth tokens.',
      content: {
        'application/json': {
          schema: z.record(
            z.string(),
            z
              .xor([
                z
                  .object({
                    userId: z.string().exactOptional(),
                    scopes: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description:
                          'Comma-separated list of scopes. Empty string if the token has no scopes.',
                      }),
                    expires: z
                      .int()
                      .nullable()
                      .exactOptional()
                      .openapi({
                        description:
                          'Unix-timestamp in milliseconds or null if the token never expires.',
                      }),
                  })
                  .openapi({ required: [] }),
                z.null().nullable(),
              ])
              .openapi({ 'x-additionalPropertiesName': 'token' }),
          ),
          examples: { default: OauthTestMultipleOauthTokensJsonExample },
        },
      },
    },
  },
  security: [],
})

export const getMastersRoute = createRoute({
  method: 'get',
  path: '/masters',
  tags: ['Opening Explorer'],
  summary: 'Masters database',
  description:
    '**Endpoint: <https://explorer.lichess.org/masters>**\n\nExample: `curl https://explorer.lichess.org/masters?play=d2d4,d7d5,c2c4,c7c6,c4d5`\n',
  operationId: 'openingExplorerMaster',
  request: {
    query: z.object({
      fen: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'fen',
            description: 'X-FEN of the root position',
            schema: { type: 'string' },
            example: 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1',
            required: false,
          },
        }),
      play: z
        .string()
        .default('')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'play',
            description:
              'Comma separated sequence of legal moves in UCI notation.\nPlay additional moves starting from `fen`.\nRequired to find an opening name, if `fen` is not an exact match\nfor a named position.\n',
            schema: { type: 'string', default: '' },
            example: 'd2d4,d7d5,c2c4,c7c6,c4d5',
            required: false,
          },
        }),
      since: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(1952)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'since',
            description: 'Include only games from this year or later',
            schema: { type: 'integer', default: 1952 },
            required: false,
          },
        }),
      until: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'until',
            description: 'Include only games from this year or earlier',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      moves: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(12)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'moves',
            description: 'Number of most common moves to display',
            schema: { type: 'integer', default: 12 },
            required: false,
          },
        }),
      topGames: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().max(15),
        )
        .default(15)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'topGames',
            description: 'Number of top games to display',
            schema: { type: 'integer', default: 15, maximum: 15 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Opening statistics and game references for the position.',
      content: {
        'application/json': {
          schema: OpeningExplorerMastersSchema,
          examples: { default: OpeningExplorerMastersJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
  },
  security: [{ OAuth2: [] }],
  servers: [
    { url: 'https://explorer.lichess.org' },
    { url: 'http://localhost:{port}', variables: { port: { default: '9002' } } },
  ],
})

