export const getStandardRoute = createRoute({
  method: 'get',
  path: '/standard',
  tags: ['Tablebase'],
  summary: 'Tablebase lookup',
  description:
    '**Endpoint: <https://tablebase.lichess.org>**\n\nExample: `curl http://tablebase.lichess.org/standard?fen=4k3/6KP/8/8/8/8/7p/8_w_-_-_0_1`\n',
  operationId: 'tablebaseStandard',
  request: {
    query: z.object({
      fen: z
        .string()
        .openapi({
          param: {
            in: 'query',
            name: 'fen',
            description: 'X-FEN of the position. Underscores allowed.',
            schema: { type: 'string' },
            required: true,
          },
        }),
      dtc: z
        .enum(['never', 'auxiliary', 'always'])
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'dtc',
            description:
              'When to query the tablebase for `dtc` values. The default is\n`auxiliary`, i.e., only when the position is not covered by one of the\nother tablebases.\n',
            schema: { type: 'string', enum: ['never', 'auxiliary', 'always'] },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The tablebase information for the position in standard chess.',
      content: {
        'application/json': {
          schema: TablebaseJsonSchema,
          examples: { default: TablebaseLookupStandardJsonExample },
        },
      },
      headers: z.object({
        'Access-Control-Allow-Origin': {
          schema: z
            .string()
            .default("'*'")
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
  },
  security: [],
  servers: [
    { url: 'https://tablebase.lichess.org' },
    { url: 'http://localhost:{port}', variables: { port: { default: '9000' } } },
  ],
})

